input.turtle:
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix dcterms: <http://purl.org/dc/terms/> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix ex: <https://example.org/voc/> .

ex:scheme a skos:ConceptScheme ;
  skos:prefLabel "Taxonomy"@en .

ex:animal a skos:Concept ;
  skos:inScheme ex:scheme ;
  skos:topConceptOf ex:scheme ;
  skos:prefLabel "Animal"@en ;
  skos:altLabel "Creature"@en ;
  skos:definition "A living organism that feeds on organic matter and can move by its own means."@en ;
  skos:narrower ex:cat ;
  dcterms:source <https://example.org/sources/zoology> .

ex:cat a skos:Concept ;
  skos:inScheme ex:scheme ;
  skos:prefLabel "Cat"@en, "Chat"@fr ;
  skos:notation "C-1" ;
  skos:scopeNote "Domestic cats only."@en ;
  skos:exactMatch <https://other.example/voc/cat> ;
  skos:broader ex:animal, ex:missing ;
  skos:definition "A small domesticated feline kept as a pet or to control mice and rats."@en .

ex:Thing a owl:Class .
